{"title":"Asking Clarifying Questions in Open-Domain Information-Seeking Conversations","url":"https://arxiv.org/abs/1907.06554","arxiv_id":"1907.06554","doi":"10.1145/3331184.3331265","authors":["Mohammad Aliannejadi","Hamed Zamani","Fabio Crestani","W. Bruce Croft"],"year":2019,"abstract":"Studies clarification as a response to incompletely expressed information needs and introduces a framework in which clarifying-question selection precedes document retrieval, making the work directly relevant to detecting and filling missing conversational context.","venue":"SIGIR 2019"}
{"title":"MIMICS: A Large-Scale Data Collection for Search Clarification","url":"https://arxiv.org/abs/2006.10174","arxiv_id":"2006.10174","doi":"10.1145/3340531.3412772","authors":["Hamed Zamani","Gord Lueck","Everest Chen","Rodolfo Quispe","Flint Luu","Nick Craswell"],"year":2020,"abstract":"Presents large-scale search-interaction data containing clarifying questions, candidate answers, and user feedback, supporting research on recognizing and resolving underspecified information needs.","venue":"CIKM 2020"}
{"title":"Query Resolution for Conversational Search with Limited Supervision","url":"https://arxiv.org/abs/2005.11723","arxiv_id":"2005.11723","doi":"10.1145/3397271.3401130","authors":["Nikos Voskarides","Dan Li","Pengjie Ren","Evangelos Kanoulas","Maarten de Rijke"],"year":2020,"abstract":"Introduces QuReTeC for resolving underspecified conversational queries by selecting useful terms from dialogue history and shows how the resolved query improves passage retrieval under limited supervision.","venue":"SIGIR 2020"}
{"title":"Open-Retrieval Conversational Question Answering","url":"https://arxiv.org/abs/2005.11364","arxiv_id":"2005.11364","authors":["Chen Qu","Liu Yang","Cen Chen","Minghui Qiu","W. Bruce Croft","Mohit Iyyer"],"year":2020,"abstract":"Formulates conversational QA without a pre-supplied evidence passage, requiring retrieval from a large corpus before reranking and answer extraction while using conversation history to contextualize the information need."}
{"title":"Weakly-Supervised Open-Retrieval Conversational Question Answering","url":"https://arxiv.org/abs/2103.02537","arxiv_id":"2103.02537","authors":["Chen Qu","Liu Yang","Cen Chen","W. Bruce Croft","Kalpesh Krishna","Mohit Iyyer"],"year":2021,"abstract":"Develops weak supervision for retrieving conversational evidence when answers can be free-form or paraphrastic, extending open-retrieval conversational QA beyond exact answer-span supervision."}
{"title":"Few-Shot Conversational Dense Retrieval","url":"https://arxiv.org/abs/2105.04166","arxiv_id":"2105.04166","doi":"10.1145/3404835.3462856","authors":["Shi Yu","Zhenghao Liu","Chenyan Xiong","Tao Feng","Zhiyuan Liu"],"year":2021,"abstract":"Introduces ConvDR, which learns contextualized dense representations for conversational retrieval and is designed to retain informative prior context while suppressing irrelevant dialogue history.","venue":"SIGIR 2021"}
{"title":"CONQRR: Conversational Query Rewriting for Retrieval with Reinforcement Learning","url":"https://arxiv.org/abs/2112.08558","arxiv_id":"2112.08558","doi":"10.18653/v1/2022.emnlp-main.679","authors":["Zeqiu Wu","Yi Luan","Hannah Rashkin","David Reitter","Hannaneh Hajishirzi","Mari Ostendorf","Gaurav Singh Tomar"],"year":2022,"abstract":"Trains conversational query rewriting directly against retrieval rewards, connecting contextual resolution to whether downstream evidence can actually be retrieved rather than optimizing rewriting alone.","venue":"EMNLP 2022"}
{"title":"ConvGQR: Generative Query Reformulation for Conversational Search","url":"https://arxiv.org/abs/2305.15645","arxiv_id":"2305.15645","doi":"10.18653/v1/2023.acl-long.274","authors":["Fengran Mo","Kelong Mao","Yutao Zhu","Yihong Wu","Kaiyu Huang","Jian-Yun Nie"],"year":2023,"abstract":"Combines conversational query rewriting with generation of potential answers and knowledge infusion so that reformulation is explicitly tied to downstream retrieval effectiveness.","venue":"ACL 2023"}
{"title":"Active Retrieval Augmented Generation","url":"https://arxiv.org/abs/2305.06983","arxiv_id":"2305.06983","doi":"10.18653/v1/2023.emnlp-main.495","authors":["Zhengbao Jiang","Frank F. Xu","Luyu Gao","Zhiqing Sun","Qian Liu","Jane Dwivedi-Yu","Yiming Yang","Jamie Callan","Graham Neubig"],"year":2023,"abstract":"Introduces active retrieval during generation, including FLARE, which anticipates upcoming content and triggers retrieval when generation confidence indicates that additional external evidence is needed.","venue":"EMNLP 2023"}
{"title":"Self-Knowledge Guided Retrieval Augmentation for Large Language Models","url":"https://arxiv.org/abs/2310.05002","arxiv_id":"2310.05002","doi":"10.18653/v1/2023.findings-emnlp.691","authors":["Yile Wang","Peng Li","Maosong Sun","Yang Liu"],"year":2023,"abstract":"Uses an estimate of an LLM's own knowledge to determine whether external retrieval should be invoked, avoiding retrieval for questions judged answerable from existing knowledge.","venue":"Findings of EMNLP 2023"}
{"title":"Self-RAG: Learning to Retrieve, Generate, and Critique through Self-Reflection","url":"https://arxiv.org/abs/2310.11511","arxiv_id":"2310.11511","authors":["Akari Asai","Zeqiu Wu","Yizhong Wang","Avirup Sil","Hannaneh Hajishirzi"],"year":2024,"abstract":"Trains a model to retrieve on demand and emit reflection signals that critique retrieved passages and generated claims, allowing retrieval to be skipped or repeated according to perceived need and support.","venue":"ICLR 2024"}
{"title":"Adaptive-RAG: Learning to Adapt Retrieval-Augmented Large Language Models through Question Complexity","url":"https://arxiv.org/abs/2403.14403","arxiv_id":"2403.14403","authors":["Soyeong Jeong","Jinheon Baek","Sukmin Cho","Sung Ju Hwang","Jong C. Park"],"year":2024,"abstract":"Routes questions among no-retrieval, single-step retrieval, and iterative retrieval strategies according to predicted question complexity, providing a learned mechanism for varying retrieval effort."}
{"title":"DRAGIN: Dynamic Retrieval Augmented Generation based on the Information Needs of Large Language Models","url":"https://arxiv.org/abs/2403.10081","arxiv_id":"2403.10081","doi":"10.18653/v1/2024.acl-long.702","authors":["Weihang Su","Yichen Tang","Qingyao Ai","Zhijing Wu","Yiqun Liu"],"year":2024,"abstract":"Models a language model's changing information needs during generation to determine both when retrieval should occur and what query should be issued for the missing information.","venue":"ACL 2024"}
{"title":"SeaKR: Self-aware Knowledge Retrieval for Adaptive Retrieval Augmented Generation","url":"https://arxiv.org/abs/2406.19215","arxiv_id":"2406.19215","authors":["Zijun Yao","Weijian Qi","Liangming Pan","Shulin Cao","Linmei Hu","Weichuan Liu","Lei Hou","Juanzi Li"],"year":2025,"abstract":"Uses uncertainty in model internal states to trigger retrieval, reranks retrieved knowledge according to uncertainty reduction, and supports repeated retrieval when current evidence remains inadequate.","venue":"ACL 2025"}
{"title":"Sufficient Context: A New Lens on Retrieval Augmented Generation Systems","url":"https://arxiv.org/abs/2411.06037","arxiv_id":"2411.06037","authors":["Hailey Joren","Jianyi Zhang","Chun-Sung Ferng","Da-Cheng Juan","Ankur Taly","Cyrus Rashtchian"],"year":2025,"abstract":"Defines and studies whether retrieved context contains enough information to answer a question, develops context-sufficiency classification, and examines selective answering and abstention when evidence is insufficient.","venue":"ICLR 2025"}
{"title":"Review-Then-Refine: A Dynamic Framework for Multi-Hop Question Answering with Temporal Adaptability","url":"https://arxiv.org/abs/2412.15101","arxiv_id":"2412.15101","authors":["Xiangsen Chen","Xuming Hu","Nan Tang"],"year":2024,"abstract":"Uses dynamically refined subqueries and temporal information during multi-hop retrieval, allowing retrieval behavior to respond to accumulated evidence instead of following an unchanged initial query."}
{"title":"Know Before You Fetch: Calibrated Retrieval-Budget Allocation for Retrieval-Augmented Generation","url":"https://arxiv.org/abs/2606.29959","arxiv_id":"2606.29959","authors":["Zhe Dong","Fang Qin","Manish Shah","Yicheng Wang"],"year":2026,"published":"2026-06-29","abstract":"Formulates adaptive RAG as calibrated allocation among closed-book answering, compact retrieval, larger retrieval, and abstention, explicitly exposing retrieval budget together with latency and token-cost trade-offs."}
{"title":"AB-RAG: Adaptive Budgeted Retrieval-Augmented Generation for Reliable Question Answering","url":"https://arxiv.org/abs/2606.29090","arxiv_id":"2606.29090","authors":["Ansh Kamthan"],"year":2026,"published":"2026-06-27","abstract":"Estimates answer confidence from model certainty, evidence agreement, and retrieval-score variation, then chooses whether to stop or retrieve additional evidence subject to an explicit retrieval budget."}
{"title":"S2G-RAG: Structured Sufficiency and Gap Judging for Iterative Retrieval-Augmented QA","url":"https://arxiv.org/abs/2604.23783","arxiv_id":"2604.23783","doi":"10.18653/v1/2026.acl-long.1185","authors":["Minghan Li","Junjie Zou","Xinxuan Lv","Chao Zhang","Guodong Zhou"],"year":2026,"abstract":"Introduces an explicit controller that judges whether accumulated evidence is sufficient and, when it is not, emits structured descriptions of the missing evidence; those gap items become the next retrieval query, while a compact evidence context limits accumulation of irrelevant text.","venue":"ACL 2026"}
{"title":"When Should Multi-Round RAG Stop? Structured Stopping Judgments and Retrieval Reduction in Search-R1","url":"https://arxiv.org/abs/2608.13237","arxiv_id":"2608.13237","authors":["Weimeng Luo"],"year":2026,"published":"2026-08-13","abstract":"Treats multi-round retrieval stopping as a sequential decision and applies structured sufficiency-and-gap judgments to decide the first state at which retrieval should terminate rather than relying only on a fixed search budget."}
{"title":"AdaKG-RAG: Adaptive KG-guided retrieval-augmented generation with hypothesis-and-verification retrieval for multi-hop question answering","url":"https://doi.org/10.1007/s44443-026-01028-3","doi":"10.1007/s44443-026-01028-3","authors":["Mengsi Yuan","Tao Wang","Yurong Qian"],"year":2026,"published":"2026-07-11","abstract":"Uses hypothesis-and-verification retrieval in a closed loop and evaluates evidence sufficiency, support consistency, confidence, and missing evidence to guide subsequent retrieval for multi-hop questions.","venue":"Journal of King Saud University Computer and Information Sciences"}
{"title":"CORAL: Adaptive Retrieval Loop for Culturally-Aligned Multilingual RAG","url":"https://arxiv.org/abs/2604.25676","arxiv_id":"2604.25676","doi":"10.18653/v1/2026.findings-acl.1356","authors":["Nayeon Lee","Jiwoo Song","Byeongcheol Kang"],"year":2026,"abstract":"Iteratively selects a retrieval corpus, retrieves evidence, critiques its relevance and alignment, checks sufficiency, and, when evidence is insufficient, changes the corpus selection and rewrites the retrieval query.","venue":"Findings of ACL 2026"}
{"title":"Adaptive iterative retrieval for enhanced retrieval-augmented generation","url":"https://doi.org/10.1016/j.neucom.2025.132272","doi":"10.1016/j.neucom.2025.132272","authors":["Wenhan Han","Xiao Xiao","Yaohang Li","Jun Wang","Mykola Pechenizkiy","Meng Fang"],"year":2026,"abstract":"Presents AIR-RAG, which feeds model feedback into subsequent retrieval and document refinement so that retrieved context is progressively adjusted to better match the downstream model's information needs.","venue":"Neurocomputing"}
{"title":"Interleaving Retrieval with Chain-of-Thought Reasoning for Knowledge-Intensive Multi-Step Questions","url":"https://arxiv.org/abs/2212.10509","arxiv_id":"2212.10509","doi":"10.18653/v1/2023.acl-long.557","authors":["Harsh Trivedi","Niranjan Balasubramanian","Tushar Khot","Ashish Sabharwal"],"year":2023,"abstract":"Introduces IRCoT, which interleaves reasoning and retrieval so later retrieval queries are conditioned on facts and intermediate conclusions obtained earlier in the evidence chain.","venue":"ACL 2023"}
{"title":"Measuring and Narrowing the Compositionality Gap in Language Models","url":"https://arxiv.org/abs/2210.03350","arxiv_id":"2210.03350","doi":"10.18653/v1/2023.findings-emnlp.378","authors":["Ofir Press","Muru Zhang","Sewon Min","Ludwig Schmidt","Noah A. Smith","Mike Lewis"],"year":2023,"abstract":"Introduces self-ask, in which a model generates follow-up questions during multi-step reasoning and can send those questions to an external search system, providing a transferable mechanism for deciding the next evidence request.","venue":"Findings of EMNLP 2023"}
{"title":"Demonstrate-Search-Predict: Composing retrieval and language models for knowledge-intensive NLP","url":"https://arxiv.org/abs/2212.14024","arxiv_id":"2212.14024","authors":["Omar Khattab","Keshav Santhanam","Xiang Lisa Li","David Hall","Percy Liang","Christopher Potts","Matei Zaharia"],"year":2023,"abstract":"Introduces a programming framework that composes language-model transformations, retrieval, and grounded prediction into multi-stage programs, including multi-hop and conversational retrieval workflows.","venue":"Transactions on Machine Learning Research"}
{"title":"REAP: Enhancing RAG with Recursive Evaluation and Adaptive Planning for Multi-Hop Question Answering","url":"https://doi.org/10.1609/aaai.v40i41.40830","doi":"10.1609/aaai.v40i41.40830","authors":["Yijie Zhu","Haojie Zhou","Wanting Hong","Tailin Liu","Ning Wang"],"year":2026,"abstract":"Uses recursive evaluation and adaptive planning to represent intermediate subtasks and facts, assess the current retrieval state, and alter the retrieval trajectory as evidence accumulates.","venue":"AAAI 2026"}
{"title":"Retrieval-Augmented Generation for Multi-Hop Question Answering Based on Structured Planning","url":"https://doi.org/10.1145/3789506","doi":"10.1145/3789506","authors":["Yujiao Huang","Ling Yang","Xu-Hua Yang","Xinli Xu"],"year":2026,"published":"2026-03-06","abstract":"Introduces structured planning for multi-hop RAG to organize successive retrieval steps and reduce drift and irrelevant evidence during iterative information acquisition.","venue":"ACM Transactions on Knowledge Discovery from Data"}
{"title":"CIRAG: Construction–Integration Retrieval and Adaptive Generation for Multi-hop Question Answering","url":"https://doi.org/10.18653/v1/2026.acl-long.1203","doi":"10.18653/v1/2026.acl-long.1203","authors":["Zili Wei","Yilin Wang","Xiaocui Yang","Shi Feng","Weidong Bao","Daling Wang","Zihan Wang","Yifei Zhang"],"year":2026,"abstract":"Iteratively constructs and integrates candidate evidence and uses the resulting state to generate subsequent retrieval queries, coupling evidence accumulation with adaptive answer generation.","venue":"ACL 2026"}
{"title":"SA-RAG: Structured and adaptive retrieval-augmented generation for multi-hop question answering","url":"https://doi.org/10.1016/j.neunet.2026.109201","doi":"10.1016/j.neunet.2026.109201","authors":["Mingcong Dang","Shengling Geng","Yonghui Xu","Fubo Wang","Lizhen Cui"],"year":2026,"abstract":"Models evidence in a structured form and learns an adaptive policy over retrieval, search, completion, correction, and answering actions, with objectives that balance answer quality, evidence coverage, and efficiency.","venue":"Neural Networks"}
{"title":"Beyond Single-Shot: Multi-step Tool Retrieval via Query Planning","url":"https://doi.org/10.18653/v1/2026.findings-acl.2090","doi":"10.18653/v1/2026.findings-acl.2090","authors":["Wei Fang","James R. Glass"],"year":2026,"abstract":"Models retrieval as iterative query planning, decomposing a complex request into successive retrieval queries rather than treating source selection as a single-shot ranking problem.","venue":"Findings of ACL 2026"}
{"title":"Selective Question Answering under Domain Shift","url":"https://arxiv.org/abs/2006.09462","arxiv_id":"2006.09462","authors":["Amita Kamath","Robin Jia","Percy Liang"],"year":2020,"abstract":"Studies selective QA systems that predict when their answers are likely to be wrong and abstain under distribution shift, providing a transferable basis for distinguishing answerable states from states requiring further evidence."}
{"title":"An Initial Investigation into Fixed and Adaptive Stopping Strategies","url":"https://doi.org/10.1145/2766462.2767802","doi":"10.1145/2766462.2767802","authors":["David Maxwell","Leif Azzopardi","Kalervo Järvelin","Heikki Keskustalo"],"year":2015,"abstract":"Investigates fixed and adaptive stopping strategies in interactive information retrieval, directly addressing how search depth can depend on observed interaction rather than an invariant document-count cutoff.","venue":"SIGIR 2015"}
{"title":"An Analysis of Stopping Strategies in Conversational Search Systems","url":"https://doi.org/10.1145/3664190.3672524","doi":"10.1145/3664190.3672524","authors":["Xiao Fu","María Pérez-Ortiz","Aldo Lipani"],"year":2024,"abstract":"Studies stopping points in conversational search and identifies interaction and textual signals that can predict when a searcher terminates a conversational information-seeking process.","venue":"ICTIR 2024"}
{"title":"Online search stopping behaviors: An investigation of query abandonment and task stopping","url":"https://doi.org/10.1002/meet.2014.14505101030","doi":"10.1002/meet.2014.14505101030","authors":["Wan-Ching Wu"],"year":2015,"published":"2015-04-24","abstract":"Empirically distinguishes abandonment of the current query from termination of the overall search task and examines factors associated with each stopping decision in online information seeking.","venue":"Proceedings of the American Society for Information Science and Technology"}
{"title":"Active Learning Stopping Strategies for Technology-Assisted Sensitivity Review","url":"https://doi.org/10.1145/3397271.3401267","doi":"10.1145/3397271.3401267","authors":["Graham McDonald","Craig Macdonald","Iadh Ounis"],"year":2020,"abstract":"Examines stopping strategies for active-learning document review in sensitivity-review workflows, where documents are acquired and assessed sequentially and review effort must be bounded.","venue":"SIGIR 2020"}
{"title":"Decision-Theoretic Stopping Rules for Document Screening","url":"https://arxiv.org/abs/2606.07071","arxiv_id":"2606.07071","doi":"10.1145/3805712.3809548","authors":["Aaron H. A. Fletcher","Mark Stevenson"],"year":2026,"published":"2026-07-19","abstract":"Derives practical document-screening stopping policies from Expected Value of Perfect Information so that additional evidence is acquired only when its expected benefit justifies its cost for the underlying professional task.","venue":"SIGIR 2026"}
{"title":"The value of information as a verification and regret-preventing mechanism in algorithmic search environments","url":"https://doi.org/10.1016/j.ins.2018.03.032","doi":"10.1016/j.ins.2018.03.032","year":2018,"abstract":"Develops an information-acquisition approach based on the value of new information and a stopping criterion tied to the decision maker's current beliefs, offering a decision-theoretic foundation for cost-sensitive evidence acquisition.","venue":"Information Sciences"}
{"title":"Time-based language models","url":"https://doi.org/10.1145/956863.956951","doi":"10.1145/956863.956951","authors":["Xiaoyan Li","W. Bruce Croft"],"year":2003,"abstract":"Introduces time into language-model-based retrieval, providing an early foundation for ranking documents according to both topical evidence and temporal characteristics rather than textual similarity alone.","venue":"CIKM 2003"}
{"title":"Temporal profiles of queries","url":"https://doi.org/10.1145/1247715.1247720","doi":"10.1145/1247715.1247720","authors":["Rosie Jones","Fernando Diaz"],"year":2007,"abstract":"Models temporal profiles of queries and retrieved material, supporting retrieval systems that need to reason about how relevance and information demand vary over time.","venue":"ACM Transactions on Information Systems"}
{"title":"Improving search relevance for implicitly temporal queries","url":"https://doi.org/10.1145/1571941.1572085","doi":"10.1145/1571941.1572085","authors":["Donald Metzler","Rosie Jones","Fuchun Peng","Ruiqiang Zhang"],"year":2009,"abstract":"Addresses queries whose temporal intent is implicit and develops retrieval methods that incorporate temporal evidence when ordinary topical matching does not fully capture the user's information need.","venue":"SIGIR 2009"}
{"title":"Understanding Temporal Query Dynamics","url":"https://doi.org/10.1145/1935826.1935862","doi":"10.1145/1935826.1935862","authors":["Anagha Kulkarni","Jaime Teevan","Krysta M. Svore","Susan T. Dumais"],"year":2011,"abstract":"Analyzes how query popularity, result content, user intent, and relevance change over time, establishing distinctions useful for deciding which temporal state of a corpus should satisfy a request.","venue":"WSDM 2011"}
{"title":"VersionRAG: Version-Aware Retrieval-Augmented Generation for Evolving Documents","url":"https://arxiv.org/abs/2510.08109","arxiv_id":"2510.08109","authors":["Daniel Huwiler","Kurt Stockinger","Jonathan Fürst"],"year":2025,"published":"2025-10-09","abstract":"Explicitly represents document version sequences, content boundaries, and changes between versions, then routes queries through version-aware retrieval paths to prevent semantically relevant but temporally invalid document states from being conflated."}
{"title":"Regulatory Churn Evaluation Framework (RCEF): A Reproducible Methodology for Evaluating Retrieval Systems Under Document Evolution","url":"https://doi.org/10.2139/ssrn.7111899","doi":"10.2139/ssrn.7111899","authors":["Ankur Garg","Jeffrey Esposito"],"year":2026,"abstract":"Defines an evaluation methodology for retrieval over repositories affected by revision, supersession, expiration, and amendment, emphasizing that semantic relevance is insufficient when a document is invalid for the query's temporal or applicability conditions.","venue":"SSRN"}
{"title":"Archiving scientific data","url":"https://doi.org/10.1145/564691.564693","doi":"10.1145/564691.564693","authors":["Peter Buneman","Sanjeev Khanna","Keishi Tajima","Wang-Chiew Tan"],"year":2002,"abstract":"Develops timestamp-based archival techniques for hierarchical scientific data that preserve historical versions and support retrieval of a specific prior state and its evolution over time.","venue":"SIGMOD 2002"}
{"title":"Why and Where: A Characterization of Data Provenance","url":"https://doi.org/10.1007/3-540-44503-X_20","doi":"10.1007/3-540-44503-X_20","authors":["Peter Buneman","Sanjeev Khanna","Wang-Chiew Tan"],"year":2001,"abstract":"Distinguishes why-provenance from where-provenance and formalizes how derived information can be traced to the specific source data that contributed it, providing a foundation for evidence-object identity and derivation tracking.","venue":"ICDT 2001"}
{"title":"Lineage tracing for general data warehouse transformations","url":"https://doi.org/10.1007/s00778-002-0083-8","doi":"10.1007/s00778-002-0083-8","authors":["Yingwei Cui","Jennifer Widom"],"year":2003,"abstract":"Develops lineage tracing for derived warehouse data so that an output item can be mapped back to the concrete source items and transformations responsible for it.","venue":"The VLDB Journal"}
{"title":"Enabling Large Language Models to Generate Text with Citations","url":"https://arxiv.org/abs/2305.14627","arxiv_id":"2305.14627","doi":"10.18653/v1/2023.emnlp-main.398","authors":["Tianyu Gao","Howard Yen","Jiatong Yu","Danqi Chen"],"year":2023,"abstract":"Introduces ALCE for generating answers grounded in retrieved sources with explicit citations and evaluates whether cited evidence actually supports the corresponding generated claims, making concrete evidence provenance inspectable.","venue":"EMNLP 2023"}
{"title":"Document access in a multi-party information management system","url":"https://doi.org/10.1109/SOLI.2008.4686509","doi":"10.1109/SOLI.2008.4686509","authors":["Trieu C. Chieu","Thao Nguyen","Kakan Roy"],"year":2008,"abstract":"Presents a sequencing access model for enterprise documents that represents who may retrieve a particular document version and when, tracks changing access privileges during workflows, and incorporates access-control information into secure retrieval indexes.","venue":"SOLI 2008"}
{"title":"Secure search of private documents in an enterprise content management system","url":"https://doi.org/10.1109/ICEBE.2007.80","doi":"10.1109/ICEBE.2007.80","authors":["Trieu C. Chieu","Thao Nguyen","Liangzhao Zeng"],"year":2007,"abstract":"Integrates document access-control information with enterprise search indexing and query construction so that private organizational documents can be retrieved according to the requesting user's role and organizational context.","venue":"ICEBE 2007"}
{"title":"Access Rights in Enterprise Full-Text Search - Searching Large Intranets Effectively using Virtual Terms","url":"https://doi.org/10.5220/0002896900320039","doi":"10.5220/0002896900320039","authors":["Jan Kasprzak","Michal Brandejs","Matěj Čuhel","Tomáš Obšívač"],"year":2010,"abstract":"Encodes access rights as virtual terms in an enterprise full-text index, integrating authorization constraints into retrieval rather than relying solely on expensive post-retrieval filtering.","venue":"ICEIS 2010"}
{"title":"Permission-Aware RAG: Identity and Access Management (IAM)-Based Access Filtering in Multi-Resource Environments","url":"https://doi.org/10.1109/ACCESS.2025.3628960","doi":"10.1109/ACCESS.2025.3628960","authors":["Jooyoung Jeong","Sang Goo Lee"],"year":2025,"published":"2025-11-04","abstract":"Enforces resource-level authorization during RAG by validating access in real time against the native IAM systems of independently governed sources, preserving their authorization boundaries instead of merging all policies into a common retrieval store.","venue":"IEEE Access"}
{"title":"Privacy-provisioned-permission-aware RAG in cloud using identity and access management, trust and large-language models (PPPARITL)","url":"https://doi.org/10.1038/s41598-026-71936-x","doi":"10.1038/s41598-026-71936-x","authors":["Urvashi Rahul Saxena","Samar Shailendra","Rajan Kadel","Mohammad Tahidul Islam","Aakanksha Sharma"],"year":2026,"published":"2026-09-13","abstract":"Introduces permission-aware RAG in which identity and access-management rules gate candidate evidence before ranking, with role-resource-action-condition authorization, trust assessment, and protected embeddings intended for enterprise cloud retrieval.","venue":"Scientific Reports"}
===END llm_candidates.jsonl===
